// Default-property synthesis, like py_aep's `synthesize_layer_properties`: ExtendScript (and the Scene oracle) always report
// a fixed set of property groups / properties per layer even when the .aep only stores the ones that differ from the AE
// defaults. The evaluator relies on them (e.g. the default Position = comp centre). Nodes created here carry
// `synthetic: true`. Tables: specData.js (generated by scripts/mogrt/gen_aep_specs.py).
import { SPECS, PROPERTY_MIN_MAX } from './specData.js';
import { AUTO_NAMES } from './matchNames.js';

const UNBOUNDED = new Set(['ADBE R Channel Blend', 'ADBE G Channel Blend', 'ADBE B Channel Blend', 'ADBE Blend Interior', 'ADBE Blend Ranges',
  'ADBE Vector Scale', 'ADBE Vector Repeater Scale']);
const clone = (v) => (Array.isArray(v) ? v.slice() : v);
const SKIP = {};
for (const k of Object.keys(SPECS.skip)) SKIP[k] = new Set(SPECS.skip[k]);

function mkNode(r, valueOverride) {
  if (r[0] === 'g') {
    return { kind: 'group', matchName: r[1], name: r[2], enabled: r[3], groupType: r[4], children: [], synthetic: true };
  }
  const n = {
    kind: 'prop', matchName: r[1], synthetic: true, name: r[2], enabled: true, valueType: r[3], dimensions: r[4], isSpatial: r[5],
    value: clone(valueOverride !== undefined ? valueOverride : r[6]), keyframes: [], expression: null, expressionEnabled: false,
  };
  if (r[7] !== null && r[7] !== undefined) n.min = r[7];
  if (r[8] !== null && r[8] !== undefined) n.max = r[8];
  return n;
}

function setAuto(node, name) {
  if (node._auto && name) node.name = name;
}

/** py_aep `_reorder_and_fill`. */
function reorderAndFill(children, rows, o) {
  const existing = new Map();
  for (const c of children) existing.set(c.matchName, c);
  const ordered = [];
  const specMn = new Set();
  for (const r of rows) {
    const mn = r[1];
    specMn.add(mn);
    const ex = existing.get(mn);
    if (ex) {
      setAuto(ex, r[2]);
      if (r[0] === 'p' && ex.kind === 'prop') {
        const [smin, smax, hint] = [r[10], r[11], r[12]];
        if (hint) {
          if (smin === null || smin === undefined) delete ex.min; else ex.min = smin;
          if (smax === null || smax === undefined) delete ex.max; else ex.max = smax;
        } else {
          if (smin !== null && smin !== undefined) ex.min = smin;
          if (smax !== null && smax !== undefined) ex.max = smax;
        }
      }
      ordered.push(ex);
    } else if (o.skip && o.skip.has(mn)) {
      continue;
    } else if (r[r[0] === 'g' ? 5 : 9] !== null && r[r[0] === 'g' ? 5 : 9] !== undefined && r[r[0] === 'g' ? 5 : 9] > o.aeMajor) {
      continue;
    } else {
      ordered.push(mkNode(r, o.values ? o.values[mn] : undefined));
    }
  }
  if (o.tail !== 'none') {
    for (const c of children) {
      if (!specMn.has(c.matchName) && (o.tail === 'all' || c.kind === 'group')) ordered.push(c);
    }
  }
  return ordered;
}

function applyBounds(n) {
  if (n.kind !== 'prop') return;
  const b = PROPERTY_MIN_MAX[n.matchName];
  if (b) { n.min = b[0]; n.max = b[1]; }
  if (UNBOUNDED.has(n.matchName)) { delete n.min; delete n.max; }
}

function deriveLayerStyles(g) {
  let any = false;
  let blend = null;
  for (const c of g.children) {
    if (c.kind !== 'group') continue;
    if (c.matchName === 'ADBE Blend Options Group') blend = c;
    else if (c.synthetic) c.enabled = false;
    else if (c.enabled) any = true;
  }
  g.enabled = any;
  if (blend) blend.enabled = any;
}

function synthGroup(g, ctx) {
  const rows = SPECS.containers[g.matchName];
  if (rows && g.kind === 'group') g.children = reorderAndFill(g.children, rows, { aeMajor: ctx.aeMajor, tail: 'groups' });
  if (g.matchName === 'ADBE Layer Styles') deriveLayerStyles(g);
  for (const c of g.children) {
    if (c.kind === 'group') synthGroup(c, ctx);
    else applyBounds(c);
  }
}

/**
 * @param properties  top-level nodes read from the layer
 * @param info { kind: 'av'|'text'|'shape'|'camera'|'light'|'mesh'|'3dmodel', nullLayer, threeD, aeMajor, compW, compH, layerW, layerH }
 */
export function synthesizeLayer(properties, info) {
  const ctx = { aeMajor: info.aeMajor };
  const isCamLight = info.kind === 'camera' || info.kind === 'light';
  let rows = SPECS.top;
  let skip = SKIP.av;
  if (info.kind === 'camera') skip = SKIP.camera;
  else if (info.kind === 'light') skip = SKIP.light;
  else if (info.kind === 'text') skip = SKIP.text;
  else if (info.kind === 'shape') skip = SKIP.shape;
  else if (info.kind === 'mesh') { rows = SPECS.meshTop; skip = null; }
  let props = reorderAndFill(properties, rows, { skip, aeMajor: info.aeMajor, tail: 'all' });

  for (const g of props) {
    if (g.kind === 'group') {
      if (g.matchName !== 'ADBE Transform Group') synthGroup(g, ctx);
    } else {
      applyBounds(g);
      if (g.matchName === 'ADBE Time Remapping' && (g.synthetic || g._noTduM)) g.max = 0;
    }
  }

  // ---- Transform defaults (py_aep _set_transform_defaults)
  const ti = props.findIndex((g) => g.matchName === 'ADBE Transform Group');
  if (ti >= 0) {
    const tg = props[ti];
    const cw = info.compW, ch = info.compH;
    let aw, ah;
    if (isCamLight) { aw = cw; ah = ch; }
    else if (info.kind === 'text' || info.kind === 'shape' || info.kind === 'mesh' || info.kind === '3dmodel' || info.nullLayer) { aw = 0; ah = 0; }
    else { aw = info.layerW; ah = info.layerH; }
    const pos = [cw / 2, ch / 2, 0];
    const spatial = {
      'ADBE Anchor Point': [aw / 2, ah / 2, 0],
      'ADBE Position': pos,
      'ADBE Position_0': pos[0], 'ADBE Position_1': pos[1], 'ADBE Position_2': pos[2],
    };
    const values = {};
    for (const r of SPECS.transform) {
      const mn = r[1];
      let def = SPECS.fixed[mn];
      if (def === undefined) def = spatial[mn];
      let value = mn === 'ADBE Position_0' || mn === 'ADBE Position_1' || mn === 'ADBE Position_2' ? 0 : def;
      if (value === undefined) value = r[4] > 1 ? new Array(r[4]).fill(0) : 0;
      values[mn] = value;
    }
    tg.children = reorderAndFill(tg.children, SPECS.transform, { aeMajor: info.aeMajor, tail: 'none', values });
    const threeD = info.threeD || isCamLight;
    for (const c of tg.children) {
      if (c.matchName === 'ADBE Rotate Z') {
        if (threeD) { if (c._auto || c.synthetic) c.name = AUTO_NAMES['ADBE Rotate Z']; } else if (c._auto || c.synthetic) c.name = 'Rotation';
      }
      if (isCamLight && c.matchName === 'ADBE Anchor Point') c.name = 'Point of Interest';
      applyBounds(c);
    }
    if (info.nullLayer) {
      const op = tg.children.find((c) => c.matchName === 'ADBE Opacity');
      if (op && op.kind === 'prop' && op.value === 100) op.value = 0;
    }
  }
  return props;
}
